const body = $json.body || {};
const productName = body.name || '';

let keywords;
if (Array.isArray(body.keywords) && body.keywords.length > 0) {
  keywords = body.keywords;
} else {
  const stopwords = new Set(['in','mit','und','oder','für','von','an','auf','bei','aus','nach','zu','zum','zur','der','die','das','ein','eine','einen','einem','einer','des','den','dem','als','am','im','ist','sind','wird','werden','haben','hat','ich','sie','er','es','wir','ihr','sich','nicht','auch','wenn','dann','so','wie','aber','noch','nur','kann','mehr','alle','viele','verschiedenen','personalisierter','personalisierte','personalisiertem','personalisierten']);
  const words = productName.toLowerCase().split(/\s+/).filter(w => w.length > 3 && !stopwords.has(w));
  const seeds = [];
  if (words.length >= 2) seeds.push(words.slice(0, 2).join(' '));
  if (words.length >= 3) seeds.push(words.slice(0, 3).join(' '));
  if (words.length >= 1) seeds.push(words[0]);
  keywords = [...new Set(seeds)].slice(0, 3);
  if (keywords.length === 0) keywords = [productName.split(' ').slice(0, 3).join(' ')];
}

return [{ json: { product_id: body.product_id, seedKeyword: keywords[0], keywords } }];

const items = $input.all();
let allKeywords = [];

for (const item of items) {
  const d = item.json;
  const tasks = d.tasks || [];

  for (const task of tasks) {
    const results = task.result || [];
    for (const result of results) {
      const kwItems = result.items || [];

      for (const kw of kwItems) {
        // keyword_suggestions format: kw.keyword + kw.keyword_info
        if (kw.keyword && kw.keyword_info) {
          allKeywords.push({
            keyword: kw.keyword,
            volume: kw.keyword_info.search_volume || 0,
            difficulty: kw.keyword_properties?.keyword_difficulty || 50
          });
        }
        // related_keywords format: kw.keyword_data
        else if (kw.keyword_data && kw.keyword_data.keyword) {
          allKeywords.push({
            keyword: kw.keyword_data.keyword,
            volume: kw.keyword_data.keyword_info?.search_volume || 0,
            difficulty: kw.keyword_data.keyword_properties?.keyword_difficulty || 50
          });
        }
      }
    }
  }
}

// Deduplizieren
const seen = new Set();
allKeywords = allKeywords.filter(kw => {
  if (!kw.keyword || seen.has(kw.keyword)) return false;
  seen.add(kw.keyword);
  return true;
});

// Ranken: hohes Volumen + niedrige Difficulty = gut
allKeywords = allKeywords
  .map(kw => ({ ...kw, score: kw.volume / (kw.difficulty + 1) }))
  .sort((a, b) => b.score - a.score);

const topKeywords = allKeywords.slice(0, 20).map(kw => kw.keyword);

return [{ json: { topKeywords, allKeywords } }];
